{
 "schema_version":1,
 "workstream_id": "ws-20261014T234009Z-RN9X",
 "run_id": "run-1792021385197",
 "node_id": "intake.claude_brainstorm",
 "result": {
 "artifact_type": "task_contract_proposal",
 "decision": "READY_FOR_PRODUCT_REVIEW",
 "summary": "已按 Must Fix删除固定文件集合的排除项，并以 C-3 与 TR-4保留 EXECUTION精确授权边界，契约可提交产品审查。",
 "needs_human_input": false,
 "objective": "在本地 Python仓库中交付 normalize_newlines(text: str) -> str：将 CRLF 与单独 CR统一转换为 LF，保留其他所有字符、空串、已有 LF 以及末尾换行的有/无，并附带标准库 unittest测试与 README 用法说明。",
 "scope": {
 "included": [
 {"path": "src/normalize_text.py"},
 {"path": "tests/test_normalize_text.py"},
 {"path": "README.md"}
 ],
 "excluded": [
 "不修改 .git/ 下任何内容",
 "不修改 .agent/工作流账本或上下文产物",
 "不在排除项中提前固定或限制实现文件集合；除 EXECUTION阶段经批准的精确、穷尽 scope.included 所列路径外，不创建或修改任何其他仓库文件"
 ]
 },
 "acceptance_criteria": [
 {"id": "AC-1", "text": "测试源码至少覆盖八类输入并各有明确期望结果：空串、纯 LF、CRLF、单独 CR、混合换行、Unicode 内容、末尾有/无换行、连续空行；且重复调用 normalize_newlines 得到相同结果（幂等）。"},
 {"id": "AC-2", "text": "实际执行 unittest测试并记录真实运行输出，输出明确显示用例覆盖数（如 Ran N tests）且 failure=0、error=0，运行结果与测试源码中的案例相符；仅有测试完成状态或文字结论不能替代实际输入/输出与测试结果（本任务不要求独立测量的真实退出码）。"},
 {"id": "AC-3", "text": "README示例与 src/normalize_text.py代码一致，包含函数导入方式和典型混合换行输入/输出示例，并通过实际读取源码/文档或执行示例来支持该结论。"}
 ],
 "test_requirements": [
 {"id": "TR-1", "text": "使用 Python标准库 unittest 编写 tests/test_normalize_text.py，覆盖 AC-1 所列至少八类输入并包含幂等性断言（对规范化结果再次规范化保持不变）。"},
 {"id": "TR-2", "text": "以 python -m unittest（或等价标准库方式）实际运行测试并保存真实 stdout，展示 Ran 数量与 OK /0 failures、0 errors 结果，作为 AC-2 的证据。"},
 {"id": "TR-3", "text": "实际读取 src/normalize_text.py 与 README.md 并比对（或直接执行 README示例代码），确认导入路径、函数名与混合换行输入/输出一致，作为 AC-3 的证据。"},
 {"id": "TR-4", "text": "交付验证时核对实际发生的文件变更与最终批准的 EXECUTION scope.included完全一致（每项一个仓库相对路径及 CREATE 或 MODIFY 操作逐项对应），确认没有任何未声明路径被创建或修改。"}
 ],
 "constraints": [
 {"id": "C-1", "text": "仅使用 Python标准库；不得引入第三方依赖，不得使用网络、数据库、浏览器、后台服务，也不得修改机器配置。"},
 {"id": "C-2", "text": "语义边界：仅将 CRLF 与单独 CR转换为 LF；不得增删或改变其他任何字符（含 Unicode）、空串、已有 LF，以及末尾换行的有/无。"},
 {"id": "C-3", "text": "src/normalize_text.py、tests/test_normalize_text.py、README.md仅为待设计与计划确认的提案路径，不得通过 GOAL阶段的排除项提前固定实现文件集合；实现前须单独批准精确、穷尽的 EXECUTION scope.included，其中每项仅包含一个仓库相对路径及 CREATE 或 MODIFY 操作，任何未声明路径均不得变更。"}
 ],
 "non_goals": [
 {"id": "NG-1", "text": "不做换行转换以外的文本规范化，如去除行尾空白、Unicode规范化（NFC/NFD）、制表符或全半角转换。"},
 {"id": "NG-2", "text": "不提供命令行入口、打包发布、CI 配置或与其他仓库/系统的集成。"},
 {"id": "NG-3", "text": "不引入第三方依赖，不进行网络访问、数据库、浏览器、后台服务调用或机器配置修改。"}
 ],
 "risk_areas": [
 {"id": "R-1", "text": "CRLF 与单独 CR 的转换顺序需正确（先处理 CRLF 再处理剩余 CR，或使用等价的一次遍历替换），避免出现 CR LF被拆成两个 LF 或残留 CR 的边界错误。"},
 {"id": "R-2", "text": "仓库 tracked inventory 为0，src/ 与 tests/ 目录尚不存在，需在实现时新建目录结构；因此 evidence_refs 为空且无既有产品文件可引用。"},
 {"id": "R-3", "text": "README示例若纯手工书写可能与代码实现漂移，须按 TR-3 通过实际读取或执行示例验证一致性。"}
 ],
 "evidence_refs": [],
 "open_questions": [],
 "revision_responses": [
 {
 "review_obligation_id": "CO-1",
 "resolved_by_clause_ids": ["C-3", "TR-4"],
 "response": "已删除原 scope.excluded 中固定三个建议文件集合的排除项，改写为不提前固定实现文件集合、仅以 EXECUTION阶段批准的精确穷尽 scope.included授权文件变更；同时以 C-3 明确三个建议路径保持提案性质及每项一个仓库相对路径加 CREATE 或 MODIFY 的单独批准要求，并以新增 TR-4 在交付验证时核对实际变更与获批 scope.included完全一致、未声明路径不得变更。"
 }
 ],
 "base_proposal_id": "node-intake-claude_brainstorm-002:10e582f4007c97e2"
 }
}
